"use client";
import { useId, useMemo, useState } from "react";
import { Badge } from "@ui/badge";
import { Button } from "@ui/button";
import { Container, ContainerBody, ContainerFooter, ContainerHeader } from "@ui/container";
import { InlineNotice } from "@ui/inline-notice";
import { Tabs, TabsList, TabItem, TabPanel } from "@ui/tabs";
import { Tooltip, TooltipProvider } from "@ui/tooltip";
import { useIcon } from "@lib/icon-context";
import { cn } from "@lib/utils";
import { allocateContextWindowCells, contextWindowCategories, contextWindowColors, getContextWindowUsage } from "./context-window/data";
import { contextWindowEnglishLabels } from "./context-window/labels";
import type { ContextWindowCategory, ContextWindowProps, ContextWindowTab } from "./context-window/types";
const contentTabs = ["docs", "memory", "history"] as const;
const tokenFormatter = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const isContentTab = (category: string): category is ContextWindowTab => contentTabs.some((tab) => tab === category);
function validNumber(value: number | null | undefined): value is number {
    return typeof value === "number" && Number.isFinite(value) && value >= 0;
}
function tokenText(value: number | null | undefined) {
    return validNumber(value) ? tokenFormatter.format(value).replace(/K$/, "k") : "—";
}
/** Embedded, controlled context snapshot. All data mutations belong to the host. */
export function ContextWindow({ data, title, live = false, tab, defaultTab = "docs", onTabChange, onCompact, compacting = false, onSettings, onClose, footerActions, notice, labels: suppliedLabels, locale = "en-US", currency = "USD", loading = false, error, onRetry, className }: ContextWindowProps) {
    const labels = { ...contextWindowEnglishLabels, ...suppliedLabels };
    const headingId = useId();
    const [localTab, setLocalTab] = useState<ContextWindowTab>(defaultTab);
    const [highlight, setHighlight] = useState<ContextWindowCategory | null>(null);
    const activeTab = tab ?? localTab;
    const usage = useMemo(() => getContextWindowUsage(data), [data]);
    const cells = useMemo(() => usage ? allocateContextWindowCells(usage.totals, data.capacity) : [], [usage, data.capacity]);
    const { integer, percent, money } = useMemo(() => ({
        integer: new Intl.NumberFormat(locale, { maximumFractionDigits: 0 }),
        percent: new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 0 }),
        money: new Intl.NumberFormat(locale, { style: "currency", currency }),
    }), [locale, currency]);
    const cache = data.cache;
    const hitRate = cache?.hitRate;
    const validHitRate = validNumber(hitRate) && hitRate <= 1 ? hitRate : null;
    const hitRateText = validHitRate === null ? "—" : percent.format(validHitRate);
    const Settings = useIcon("settings");
    const Close = useIcon("x");
    const Pin = useIcon("pin");
    const Compact = useIcon("scissors");
    const Info = useIcon("doc-info-item");
    function changeTab(value: string) {
        if (!isContentTab(value))
            return;
        if (tab === undefined)
            setLocalTab(value);
        onTabChange?.(value);
    }
    function categoryDetails(category: ContextWindowCategory) {
        const records = isContentTab(category) ? data[category] : [];
        return <div className="max-w-72 space-y-2 text-label">
      <div className="flex justify-between gap-4 font-medium"><span>{labels[category]}</span><span className="tabular-nums">{tokenText(usage?.totals[category])} {labels.tokens}</span></div>
      {records.slice(0, 3).map((item) => <div key={item.id} className="flex justify-between gap-4"><span className="min-w-0 truncate opacity-70">{item.title}</span><span className="shrink-0 tabular-nums">{tokenText(item.tokens)}</span></div>)}
    </div>;
    }
    return <TooltipProvider><Container data-block="context-window" role="region" aria-labelledby={headingId} className={cn("w-full", className)}>
    <ContainerHeader className="py-2">
      <div className="flex min-w-0 flex-1 items-center gap-2">
        <h2 id={headingId} className="min-w-0 break-words text-body font-medium text-fg-default">{title ?? labels.title}</h2>
        <Tooltip content={labels.description}><Button type="button" variant="ghost" size="xs" iconOnly aria-label={labels.description}><Info aria-hidden="true"/></Button></Tooltip>
      </div>
      <div className="flex items-center gap-1">
        <Badge status={live ? "success" : "neutral"} variant="dot" size="sm">{live ? labels.live : labels.paused}</Badge>
        {onSettings && <Tooltip content={labels.settings}><Button type="button" variant="ghost" size="sm" iconOnly aria-label={labels.settings} onClick={onSettings}><Settings aria-hidden="true"/></Button></Tooltip>}
        {onClose && <Button type="button" variant="ghost" size="sm" iconOnly aria-label={labels.close} onClick={onClose}><Close aria-hidden="true"/></Button>}
      </div>
    </ContainerHeader>
    {loading || error || !usage ? <ContainerBody><div className="flex min-h-48 items-center justify-center gap-3" aria-busy={loading}>
      <InlineNotice role={loading ? "status" : "alert"}>{loading ? labels.loading : error ?? labels.invalid}</InlineNotice>
      {!loading && onRetry && <Button type="button" variant="secondary" onClick={onRetry}>{labels.retry}</Button>}
    </div></ContainerBody> : <>
      <ContainerBody>
        <div className="grid min-w-0 gap-5 sm:grid-cols-5">
          <div className={cn("min-w-0 space-y-2", cache ? "sm:col-span-3" : "sm:col-span-5")}>
            <div className="flex flex-wrap items-center gap-2"><span className="font-mono text-label uppercase tracking-wider text-fg-subtle">{labels.used}</span><Badge status={usage.status} size="sm">{usage.status === "success" ? labels.healthy : usage.status === "warning" ? labels.warning : labels.full}</Badge></div>
            <div className="flex flex-wrap items-baseline gap-2"><span className="text-display font-medium tracking-tight text-fg-default tabular-nums">{tokenText(usage.used)}</span><span className="text-body text-fg-subtle">/ {tokenText(data.capacity)} {labels.tokens}</span></div>
            <p className="flex flex-wrap gap-x-2 font-mono text-label text-fg-muted"><span>{labels.usage(percent.format(usage.ratio))}</span>{usage.headroom !== null && <span>· {labels.headroom(integer.format(usage.headroom))}</span>}</p>
          </div>
          {cache && (<div className="min-w-0 space-y-2 sm:col-span-2">
              <div className="flex flex-wrap justify-between gap-2 font-mono text-label text-fg-subtle">
                <span className="uppercase tracking-wider">{labels.cache}</span>
                <span>{labels.hit(hitRateText)}</span>
              </div>
              <p className="flex items-baseline gap-2">
                <span className="text-heading font-medium text-fg-default tabular-nums">{validNumber(cache.saved) ? money.format(cache.saved) : "—"}</span>
                <span className="text-label text-fg-subtle">{labels.saved}</span>
              </p>
              <div className="h-1 overflow-hidden rounded-full bg-surface-raised" role={validHitRate === null ? undefined : "meter"} aria-label={labels.cache} aria-valuemin={validHitRate === null ? undefined : 0} aria-valuemax={validHitRate === null ? undefined : 100} aria-valuenow={validHitRate === null ? undefined : validHitRate * 100} aria-valuetext={validHitRate === null ? undefined : hitRateText}>
                <div className="h-full rounded-full bg-fg-muted transition-all duration-moderate motion-reduce:transition-none" style={{ width: validHitRate === null ? "0%" : `${validHitRate * 100}%` }}/>
              </div>
              <p className="font-mono text-label text-fg-subtle">{tokenText(cache.cachedTokens)} {labels.cached} · {tokenText(cache.newTokens)} {labels.newTokens}</p>
            </div>)}
        </div>
        <div className="mt-5 space-y-4">
          {/* Categorical capacity bitmap: unlike the calendar HeatmapChart it has no date or intensity axis. */}
          <Tooltip content={categoryDetails(highlight ?? "docs")}><div role="img" aria-label={labels.matrix} className="grid gap-0.5" style={{ gridTemplateColumns: "repeat(50, minmax(0, 1fr))" }} onMouseLeave={() => setHighlight(null)}>
            {cells.map((category, index) => <span key={index} aria-hidden="true" data-context-category={category} onMouseEnter={() => setHighlight(category)} className={cn("aspect-square min-w-0 rounded-xs transition-opacity duration-fast motion-reduce:transition-none", highlight !== null && highlight !== category && "opacity-20")} style={{ backgroundColor: contextWindowColors[category] }}/>)}
          </div></Tooltip>
          <ul className="grid grid-cols-3 gap-x-1.5 gap-y-3 sm:gap-x-5" aria-label={labels.matrix}>
            {contextWindowCategories.map((category) => <li key={category} className="min-w-0"><Tooltip content={categoryDetails(category)}><button type="button" className={cn("flex w-full items-center justify-between gap-0.5 rounded-sm text-left outline-none transition-opacity duration-fast focus-visible:ring-2 focus-visible:ring-focus-ring motion-reduce:transition-none sm:gap-2", highlight !== null && highlight !== category && "opacity-30")} aria-label={`${labels[category]}: ${integer.format(usage.totals[category])} ${labels.tokens}, ${percent.format(usage.totals[category] / data.capacity)}`} onMouseEnter={() => setHighlight(category)} onMouseLeave={() => setHighlight(null)} onFocus={() => setHighlight(category)} onBlur={() => setHighlight(null)} onClick={() => { if (isContentTab(category))
                changeTab(category); }}>
              <span className="flex min-w-0 items-center gap-0.5 font-mono text-label uppercase text-fg-subtle sm:gap-1.5"><span aria-hidden="true" className="size-2 shrink-0 rounded-full" style={{ backgroundColor: contextWindowColors[category] }}/><span className="truncate">{labels[category]}</span></span>
              <span className="flex shrink-0 items-baseline gap-0.5 whitespace-nowrap sm:gap-1.5"><span className="text-label font-medium text-fg-default tabular-nums sm:text-body">{tokenText(usage.totals[category])}</span><span className="text-label text-fg-subtle tabular-nums">{percent.format(usage.totals[category] / data.capacity)}</span></span>
            </button></Tooltip></li>)}
          </ul>
        </div>
      </ContainerBody>
      <ContainerBody>
        <Tabs value={activeTab} onValueChange={changeTab} variant="segment" color="default">
          <div className="mb-3 flex flex-wrap items-center justify-between gap-3">
            <div className="min-w-0"><h3 className="text-body font-medium text-fg-default">{labels.contents}</h3><p className="mt-1 font-mono text-label text-fg-subtle">{labels.summary(integer.format(data[activeTab].length), tokenText(usage.totals[activeTab]), percent.format(usage.totals[activeTab] / data.capacity))}</p></div>
            <TabsList aria-label={labels.contents}>{contentTabs.map((category) => <TabItem key={category} value={category} label={labels[category]}/>)}</TabsList>
          </div>
          {contentTabs.map((category) => {
                const maxTokens = data[category].reduce((max, item) => Math.max(max, item.tokens), 1);
                return <TabPanel key={category} value={category}>
            {data[category].length === 0 ? <p className="py-8 text-center text-body text-fg-muted">{labels.empty}</p> : <ul className="max-h-56 overflow-y-auto" aria-label={labels[category]}>
              {data[category].map((item) => {
                            return <li key={item.id} className="flex min-w-0 items-center gap-3 border-b-hairline border-border-subtle py-3 last:border-0" data-context-item={item.id}>
                  <span aria-hidden="true" className="size-2 shrink-0 rounded-full" style={{ backgroundColor: contextWindowColors[category] }}/>
                  <div className="min-w-0 flex-1"><p className="flex min-w-0 items-center gap-1.5 text-body text-fg-default"><span className="truncate" title={item.title}>{item.title}</span>{item.pinned && <Tooltip content={labels.pinned}><span className="shrink-0 text-fg-brand" aria-label={labels.pinned}><Pin className="size-3.5" aria-hidden="true"/></span></Tooltip>}</p><p className="mt-0.5 truncate font-mono text-label text-fg-subtle">{[item.source, item.detail].filter(Boolean).join(" · ")}</p></div>
                  <div className="hidden h-1 w-12 shrink-0 overflow-hidden rounded-full bg-surface-raised sm:block" aria-hidden="true"><div className="h-full rounded-full transition-all duration-moderate motion-reduce:transition-none" style={{ width: `${item.tokens / maxTokens * 100}%`, backgroundColor: contextWindowColors[category] }}/></div>
                  <span className="w-12 shrink-0 text-right text-body font-medium text-fg-default tabular-nums">{tokenText(item.tokens)}</span>
                </li>;
                        })}
            </ul>}
          </TabPanel>;
            })}
        </Tabs>
      </ContainerBody>
    </>}
    <ContainerFooter className="justify-between">
      <div className="flex min-w-0 flex-1 items-center gap-2">{footerActions}{data.session && <p className="min-w-0 truncate font-mono text-label uppercase text-fg-subtle" title={`${data.session.model} · ${labels.turn} ${data.session.turn} · ${data.session.name}`}>{data.session.model} · {labels.turn} {integer.format(data.session.turn)} · {data.session.name}</p>}</div>
      {onCompact && <Button type="button" size="sm" leadingIcon={Compact} loading={compacting} disabled={loading || Boolean(error) || !usage || data.history.every((item) => item.pinned)} onClick={onCompact}>{compacting ? labels.compacting : labels.compact}</Button>}
    </ContainerFooter>
    {notice && <div className="px-3 pb-2"><InlineNotice role="status" aria-live="polite">{notice}</InlineNotice></div>}
  </Container></TooltipProvider>;
}
export { ContextWindowCompact } from "./context-window/compact";
export { ContextWindowUsage } from "./context-window/usage";
export { contextWindowEnglishLabels, contextWindowZhLabels, contextWindowCompactEnglishLabels, contextWindowCompactZhLabels } from "./context-window/labels";
export { getContextWindowUsage, allocateContextWindowCells, contextWindowCategories, contextWindowColors } from "./context-window/data";
export type { ContextWindowCategory, ContextWindowData, ContextWindowItem, ContextWindowLabels, ContextWindowProps, ContextWindowTab, ContextWindowCompactLabels, ContextWindowCompactProps, ContextWindowUsageProps } from "./context-window/types";

import type { HTMLAttributes, ReactNode } from "react";
export type ContextWindowTab = "docs" | "memory" | "history";
export type ContextWindowCategory = "system" | "tools" | ContextWindowTab | "free";
export interface ContextWindowItem {
    id: string;
    title: string;
    tokens: number;
    /** Already-localized source and age/turn labels supplied by the host. */
    source?: string;
    detail?: string;
    pinned?: boolean;
}
export interface ContextWindowData {
    capacity: number;
    systemTokens: number;
    toolTokens: number;
    docs: readonly ContextWindowItem[];
    memory: readonly ContextWindowItem[];
    history: readonly ContextWindowItem[];
    /** Typical tokens added per turn; omit when an estimate is unavailable. */
    tokensPerTurn?: number;
    cache?: {
        hitRate: number | null;
        saved: number | null;
        cachedTokens: number | null;
        newTokens: number | null;
    };
    session?: {
        model: string;
        turn: number;
        name: string;
    };
}
export interface ContextWindowLabels {
    title: string;
    description: string;
    live: string;
    paused: string;
    settings: string;
    close: string;
    used: string;
    healthy: string;
    warning: string;
    full: string;
    tokens: string;
    cache: string;
    saved: string;
    cached: string;
    newTokens: string;
    contents: string;
    empty: string;
    system: string;
    tools: string;
    docs: string;
    memory: string;
    history: string;
    free: string;
    compact: string;
    compacting: string;
    pinned: string;
    invalid: string;
    loading: string;
    retry: string;
    turn: string;
    matrix: string;
    usage: (percent: string) => string;
    headroom: (turns: string) => string;
    hit: (percent: string) => string;
    summary: (count: string, tokens: string, percent: string) => string;
}
export interface ContextWindowProps {
    data: ContextWindowData;
    title?: string;
    live?: boolean;
    loading?: boolean;
    error?: string;
    onRetry?: () => void;
    tab?: ContextWindowTab;
    defaultTab?: ContextWindowTab;
    onTabChange?: (tab: ContextWindowTab) => void;
    onCompact?: () => void;
    compacting?: boolean;
    onSettings?: () => void;
    onClose?: () => void;
    footerActions?: ReactNode;
    notice?: string;
    labels?: Partial<ContextWindowLabels>;
    /** Localizes percentages, integer counts and currency; token abbreviations use k/M/B. */
    locale?: string;
    currency?: string;
    className?: string;
}
export interface ContextWindowUsageProps extends Omit<HTMLAttributes<HTMLSpanElement>, "children"> {
    /** The same snapshot passed to ContextWindowCompact. */
    data: ContextWindowData;
    /** Malformed locales fall back to en-US. */
    locale?: string;
}
export interface ContextWindowCompactLabels {
    title: string;
    tokens: string;
    system: string;
    tools: string;
    docs: string;
    history: string;
    memory: string;
    contents: string;
    empty: string;
    compact: string;
    compacting: string;
    loading: string;
    invalid: string;
    retry: string;
    capacity: (tokens: string) => string;
    remaining: (tokens: string) => string;
    usage: (used: string, capacity: string, percent: string) => string;
}
/** Uses the same snapshot contract as ContextWindow; the host owns mutations. */
export interface ContextWindowCompactProps {
    data: ContextWindowData;
    /** Render content directly inside a host surface, without a Container frame. */
    embedded?: boolean;
    title?: string;
    /** Overrides the default Claude logo for Claude model names. */
    modelIcon?: ReactNode;
    onCompact?: () => void;
    compacting?: boolean;
    loading?: boolean;
    error?: string;
    onRetry?: () => void;
    /** Success feedback; hidden while loading, compacting, invalid or failed. */
    notice?: string;
    labels?: Partial<ContextWindowCompactLabels>;
    /** Localizes counts and percentages; malformed locales fall back to en-US. */
    locale?: string;
    className?: string;
}

import type { ContextWindowCompactLabels, ContextWindowLabels } from "./types";
export const contextWindowEnglishLabels: ContextWindowLabels = {
    title: "Context window", description: "Token allocation across system instructions, tools, memory, documents and conversation history.",
    live: "Live", paused: "Paused", settings: "Context settings", close: "Close context window",
    used: "Context used", healthy: "Healthy", warning: "Filling up", full: "Near capacity", tokens: "tokens",
    cache: "Prompt cache", saved: "saved", cached: "cached", newTokens: "new", contents: "Contents",
    empty: "No items in this category.", system: "System", tools: "Tools", docs: "Docs", memory: "Memory", history: "History", free: "Free",
    compact: "Compact history", compacting: "Compacting history…", pinned: "Pinned",
    invalid: "Context data is invalid. Check capacity, token counts and item ids.",
    loading: "Loading context…", retry: "Retry", turn: "Turn", matrix: "Context token allocation",
    usage: (percent) => `${percent} full`, headroom: (turns) => `~${turns} turns of headroom`,
    hit: (percent) => `${percent} hit`, summary: (count, tokens, percent) => `${count} items · ${tokens} tokens · ${percent} of window`,
};
export const contextWindowZhLabels: ContextWindowLabels = {
    title: "上下文窗口", description: "查看系统指令、工具、记忆、文档与对话历史的 token 分配。",
    live: "实时", paused: "已暂停", settings: "上下文设置", close: "关闭上下文窗口",
    used: "已用上下文", healthy: "充足", warning: "接近上限", full: "容量紧张", tokens: "tokens",
    cache: "提示词缓存", saved: "已节省", cached: "已缓存", newTokens: "新增", contents: "内容",
    empty: "此分类暂无内容。", system: "系统", tools: "工具", docs: "文档", memory: "记忆", history: "历史", free: "剩余",
    compact: "压缩历史", compacting: "正在压缩历史…", pinned: "已固定",
    invalid: "上下文数据无效，请检查容量、token 数量与条目标识。",
    loading: "正在加载上下文…", retry: "重试", turn: "轮次", matrix: "上下文 token 分配",
    usage: (percent) => `已占用 ${percent}`, headroom: (turns) => `预计还可对话 ${turns} 轮`,
    hit: (percent) => `命中 ${percent}`, summary: (count, tokens, percent) => `${count} 项 · ${tokens} tokens · 占窗口 ${percent}`,
};
export const contextWindowCompactEnglishLabels: ContextWindowCompactLabels = {
    title: "Context window", tokens: "tokens", system: "System prompt", tools: "Tools",
    docs: "Files", history: "Conversation", memory: "Memory", contents: "Token breakdown",
    empty: "No files in context.", compact: "Compact", compacting: "Compacting…",
    loading: "Loading context…",
    invalid: "Context data is invalid. Check capacity, token counts and item ids.", retry: "Retry",
    capacity: (tokens) => `of ${tokens} tokens`, remaining: (tokens) => `${tokens} left`,
    usage: (used, capacity, percent) => `${used} of ${capacity} tokens used (${percent})`,
};
export const contextWindowCompactZhLabels: ContextWindowCompactLabels = {
    title: "上下文窗口", tokens: "tokens", system: "系统提示词", tools: "工具",
    docs: "文件", history: "对话", memory: "记忆", contents: "Token 分类明细",
    empty: "上下文中暂无文件。", compact: "压缩", compacting: "正在压缩…",
    loading: "正在加载上下文…",
    invalid: "上下文数据无效，请检查容量、token 数量与条目标识。", retry: "重试",
    capacity: (tokens) => `/ ${tokens} tokens`, remaining: (tokens) => `剩余 ${tokens}`,
    usage: (used, capacity, percent) => `已使用 ${used} / ${capacity} tokens（${percent}）`,
};

import type { ContextWindowCategory, ContextWindowData } from "./types";
export const contextWindowCategories: readonly ContextWindowCategory[] = ["system", "tools", "memory", "docs", "history", "free"];
export const contextWindowColors: Record<ContextWindowCategory, string> = {
    system: "var(--chart-1)", tools: "var(--chart-2)", memory: "color-mix(in oklab, var(--chart-1) 50%, var(--chart-5))",
    docs: "var(--chart-4)", history: "var(--chart-5)", free: "var(--chart-6)",
};
const validTokens = (value: number) => Number.isFinite(value) && value >= 0;
/** Totals come from the same records displayed in Contents, avoiding stale summary counters. */
export function getContextWindowUsage(data: ContextWindowData) {
    if (!Number.isFinite(data.capacity) || data.capacity <= 0 || !validTokens(data.systemTokens) || !validTokens(data.toolTokens))
        return null;
    for (const category of ["docs", "memory", "history"] as const) {
        const ids = new Set<string>();
        for (const item of data[category]) {
            if (!item.id || ids.has(item.id) || !validTokens(item.tokens))
                return null;
            ids.add(item.id);
        }
    }
    const totals: Record<ContextWindowCategory, number> = {
        system: data.systemTokens, tools: data.toolTokens,
        memory: data.memory.reduce((sum, item) => sum + item.tokens, 0),
        docs: data.docs.reduce((sum, item) => sum + item.tokens, 0),
        history: data.history.reduce((sum, item) => sum + item.tokens, 0), free: 0,
    };
    const used = totals.system + totals.tools + totals.memory + totals.docs + totals.history;
    if (!Number.isFinite(used))
        return null;
    totals.free = Math.max(0, data.capacity - used);
    const ratio = used / data.capacity;
    if (!Number.isFinite(ratio))
        return null;
    const tokensPerTurn = data.tokensPerTurn;
    const estimate = tokensPerTurn !== undefined && validTokens(tokensPerTurn) && tokensPerTurn > 0
        ? Math.floor(totals.free / tokensPerTurn)
        : null;
    const headroom = estimate !== null && Number.isFinite(estimate) ? estimate : null;
    return {
        totals, used, ratio,
        status: ratio >= 0.95 ? "danger" as const : ratio >= 0.8 ? "warning" as const : "success" as const,
        headroom,
    };
}
/** Largest-remainder allocation keeps both context layouts at their requested cell count. */
export function allocateContextWindowCells(totals: Record<ContextWindowCategory, number>, capacity: number, cellCount = 400, categories = contextWindowCategories): ContextWindowCategory[] {
    const denominator = Math.max(capacity, contextWindowCategories.reduce((sum, category) => sum + totals[category], 0));
    const counts = categories.map((category) => {
        const exact = totals[category] / denominator * cellCount;
        return { category, count: Math.floor(exact), remainder: exact % 1 };
    });
    let remaining = cellCount - counts.reduce((sum, value) => sum + value.count, 0);
    for (const value of [...counts].sort((a, b) => b.remainder - a.remainder)) {
        if (remaining-- > 0)
            value.count++;
    }
    return counts.flatMap(({ category, count }) => Array<ContextWindowCategory>(count).fill(category));
}

"use client";
import { useId, useMemo, useState } from "react";
import { Alert, AlertAction, AlertTitle } from "@ui/alert";
import { Badge } from "@ui/badge";
import { Button } from "@ui/button";
import { Container, ContainerBody, ContainerFooter } from "@ui/container";
import { InlineNotice, InlineNoticeContent } from "@ui/inline-notice";
import { useIcon } from "@lib/icon-context";
import { cn } from "@lib/utils";
import { allocateContextWindowCells, getContextWindowUsage } from "./data";
import type { ContextWindowCategory } from "./types";
import { contextWindowCompactEnglishLabels } from "./labels";
import type { ContextWindowCompactProps } from "./types";
const categories = ["system", "tools", "docs", "history", "memory"] as const;
const allocationCategories = [...categories, "free"] as const;
const colors: Record<ContextWindowCategory, string> = {
    system: "var(--fg-default)", tools: "var(--fg-subtle)",
    docs: "color-mix(in oklab, var(--fg-subtle) 45%, var(--surface-floating))",
    history: "var(--brand)", memory: "color-mix(in oklab, var(--brand) 40%, var(--surface-floating))",
    free: "var(--surface-raised)",
};
const tokens = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const tokenText = (value: number) => tokens.format(value).replace(/K$/, "k");
const fallbackFormat = {
    integer: new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }),
    percent: new Intl.NumberFormat("en-US", { style: "percent", maximumFractionDigits: 0 }),
};
export function ContextWindowCompact({ data, embedded = false, title, modelIcon, onCompact, compacting = false, loading = false, error, onRetry, notice, labels: suppliedLabels, locale = "en-US", className }: ContextWindowCompactProps) {
    const labels = { ...contextWindowCompactEnglishLabels, ...suppliedLabels };
    const id = useId();
    const [filesOpen, setFilesOpen] = useState(false);
    const usage = useMemo(() => getContextWindowUsage(data), [data]);
    const cells = useMemo(() => usage ? allocateContextWindowCells(usage.totals, data.capacity, 240, allocationCategories) : [], [usage, data.capacity]);
    const format = useMemo(() => {
        try {
            return {
                integer: new Intl.NumberFormat(locale, { maximumFractionDigits: 0 }),
                percent: new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 0 }),
            };
        }
        catch {
            return fallbackFormat;
        }
    }, [locale]);
    const Compact = useIcon("scissors");
    const Down = useIcon("chevron-down");
    const Up = useIcon("chevron-up");
    const ready = !loading && !error && usage !== null;
    const showNotice = ready && !compacting && Boolean(notice);
    const Root = embedded ? "div" : Container;
    const Body = embedded ? "div" : ContainerBody;
    const Footer = embedded ? "div" : ContainerFooter;
    return <Root data-block="context-window-compact" role="region" aria-labelledby={`${id}-heading`} aria-busy={loading} className={cn("min-w-0 w-full", className)}>
    <Body>
      <div className="flex min-w-0 flex-wrap items-center justify-between gap-2">
        <h2 id={`${id}-heading`} className="text-body font-medium text-fg-default">{title ?? labels.title}</h2>
        {data.session?.model && <Badge size="sm" leadingIcon={modelIcon}><span className="block max-w-48 truncate font-mono" title={data.session.model}>{data.session.model}</span></Badge>}
      </div>
      {!ready ? <div className="flex min-h-48 flex-wrap items-center justify-center gap-3">
        {loading ? <InlineNotice variant="emphasized" tone="info" role="status"><InlineNoticeContent>{labels.loading}</InlineNoticeContent></InlineNotice>
                : <Alert status="danger" className="w-full">
            <AlertTitle className="break-words">{error ?? labels.invalid}</AlertTitle>
            {onRetry && <AlertAction><Button type="button" variant="secondary" size="sm" onClick={onRetry}>{labels.retry}</Button></AlertAction>}
          </Alert>}
      </div> : <>
        <div className="mt-4 flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
          <div className="flex min-w-0 flex-wrap items-baseline gap-x-2 gap-y-1 text-body tabular-nums">
            <span className="font-semibold text-fg-default">{tokenText(usage.used)}</span>
            <span className="text-fg-subtle">{labels.capacity(tokenText(data.capacity))}</span>
          </div>
          <span className={cn("text-body font-medium tabular-nums", usage.status === "danger" ? "text-fg-danger" : usage.status === "warning" ? "text-fg-warning" : "text-fg-muted")}>{format.percent.format(usage.ratio)}</span>
        </div>
        {/* Categorical capacity has no date axis; use the shared context allocator. */}
        <div role="img" aria-label={labels.usage(format.integer.format(usage.used), format.integer.format(data.capacity), format.percent.format(usage.ratio))} className="mt-4 grid gap-0.5" style={{ gridTemplateColumns: "repeat(40, minmax(0, 1fr))" }}>
          {cells.map((category, index) => <span key={index} aria-hidden="true" data-context-category={category} className="aspect-square min-w-0 rounded-xs" style={{ backgroundColor: colors[category] }}/>)}
        </div>
        <ul className="mt-4 space-y-1" aria-label={labels.contents}>
          {categories.map((category) => <li key={category}>
            <div className="flex min-h-9 min-w-0 flex-wrap items-center gap-x-3 gap-y-1 text-body">
              <span aria-hidden="true" className="size-2 shrink-0 rounded-xs" style={{ backgroundColor: colors[category] }}/>
              {category === "docs" ? <Button type="button" variant="ghost" size="md" contentSized className="-ml-1.5" trailingIcon={filesOpen ? Up : Down} aria-expanded={filesOpen} aria-controls={`${id}-files`} onClick={() => setFilesOpen((open) => !open)}>{labels.docs}</Button>
                    : <span className="min-w-24 flex-1 break-words text-fg-muted">{labels[category]}</span>}
              {category === "docs" && <span className="flex-1"/>}
              <span className="ml-auto flex shrink-0 flex-wrap items-center justify-end gap-x-2 gap-y-1">
                {category === "history" && onCompact && <Button type="button" variant="ghost" size="sm" leadingIcon={Compact} loading={compacting} disabled={data.history.every((item) => item.pinned || item.tokens === 0)} onClick={onCompact}>{compacting ? labels.compacting : labels.compact}</Button>}
                <span className="min-w-12 text-right text-fg-default tabular-nums"><span aria-hidden="true">{tokenText(usage.totals[category])}</span><span className="sr-only">{format.integer.format(usage.totals[category])} {labels.tokens}</span></span>
              </span>
            </div>
            {category === "docs" && <div id={`${id}-files`} hidden={!filesOpen}>
              {filesOpen && (data.docs.length ? <ul tabIndex={0} className="my-2 max-h-40 space-y-2 overflow-y-auto rounded-sm pl-5 outline-none focus-visible:ring-1 focus-visible:ring-focus-ring" aria-label={labels.docs}>
                {data.docs.map((item) => <li key={item.id} className="flex min-w-0 items-baseline justify-between gap-3 text-label">
                  <span className="min-w-0 truncate text-fg-muted" title={item.title}>{item.title}</span>
                  <span className="shrink-0 text-fg-subtle tabular-nums"><span aria-hidden="true">{tokenText(item.tokens)}</span><span className="sr-only">{format.integer.format(item.tokens)} {labels.tokens}</span></span>
                </li>)}
              </ul> : <p className="py-2 pl-5 text-label text-fg-subtle">{labels.empty}</p>)}
            </div>}
          </li>)}
        </ul>
      </>}
    </Body>
    {ready && <Footer className={cn("justify-start", embedded && "mt-4 flex min-w-0 flex-wrap items-center gap-2")}>
      <span className="text-body text-fg-subtle tabular-nums">{labels.remaining(tokenText(usage.totals.free))}</span>
    </Footer>}
    <div role={showNotice ? "status" : undefined} aria-live="polite" aria-atomic="true" className={showNotice ? embedded ? "mt-3" : "px-3 pb-2" : "sr-only"}>
      {showNotice && <InlineNotice variant="emphasized" tone="success"><InlineNoticeContent>{notice}</InlineNoticeContent></InlineNotice>}
    </div>
  </Root>;
}

"use client";
import { useMemo } from "react";
import { PieChart, PieSlice, type PieData } from "@ui/pie-chart";
import { cn } from "@lib/utils";
import { getContextWindowUsage } from "./data";
import type { ContextWindowUsageProps } from "./types";
/** A compact readout for context triggers; the host owns the button and popover. */
export function ContextWindowUsage({ data, locale = "en-US", className, ...props }: ContextWindowUsageProps) {
    const usage = useMemo(() => getContextWindowUsage(data), [data]);
    const slices = useMemo<PieData[]>(() => usage ? [
        { label: "used", value: usage.used, color: "currentColor" },
        { label: "remaining", value: usage.totals.free, color: "var(--border)" },
    ] : [], [usage]);
    const percent = useMemo(() => {
        try {
            return new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 0 });
        }
        catch {
            return new Intl.NumberFormat("en-US", { style: "percent", maximumFractionDigits: 0 });
        }
    }, [locale]);
    return (<span data-slot="context-window-usage" className={cn("inline-flex items-center gap-1.5 align-middle text-label tabular-nums", className)} {...props}>
      {usage ? <>
        <span aria-hidden="true" inert className="pointer-events-none inline-flex size-4 shrink-0">
          <PieChart data={slices} size={16} innerRadius={6} hoverOffset={0} startAngle={0} endAngle={Math.PI * 2} hoveredIndex={null}>
            <PieSlice index={0} animate={false} showGlow={false} hoverEffect="none"/>
            <PieSlice index={1} animate={false} showGlow={false} hoverEffect="none"/>
          </PieChart>
        </span>
        <span>{percent.format(usage.ratio)}</span>
      </> : "—"}
    </span>);
}
